-- 000001 baseline = project doc 001_initial_schema.sql with ONE fix:
--   RN-22: integration.device_identities is created BEFORE device_enrollment_codes / session_tickets
--   (the original referenced it before it existed, so it failed on an empty database).
-- Do not edit this file after it has run anywhere. Put changes in a new migration.
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS core;
CREATE SCHEMA IF NOT EXISTS gaming;
CREATE SCHEMA IF NOT EXISTS commercial;
CREATE SCHEMA IF NOT EXISTS billing;
CREATE SCHEMA IF NOT EXISTS payments;
CREATE SCHEMA IF NOT EXISTS ledger;
CREATE SCHEMA IF NOT EXISTS integration;
CREATE SCHEMA IF NOT EXISTS audit;

-- Identity / tenancy
CREATE TABLE identity.users (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    keycloak_subject text NOT NULL UNIQUE,
    email citext,
    display_name text,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED','PENDING')),
    avatar_asset_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE identity.bff_sessions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES identity.users(id),
    refresh_token_ciphertext text NOT NULL,
    csrf_token_hash text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    user_agent_hash text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX idx_bff_sessions_user ON identity.bff_sessions(user_id, expires_at);
CREATE INDEX idx_bff_sessions_active ON identity.bff_sessions(expires_at) WHERE revoked_at IS NULL;

CREATE TABLE core.tenants (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    legal_name text,
    country_code char(2) NOT NULL DEFAULT 'MY',
    timezone text NOT NULL DEFAULT 'Asia/Kuala_Lumpur',
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','CLOSED','PENDING')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE core.tenant_memberships (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    user_id uuid NOT NULL REFERENCES identity.users(id),
    role text NOT NULL CHECK (role IN ('CAFE_OWNER','BRANCH_MANAGER','FLOOR_STAFF','FINANCE_VIEWER')),
    branch_id uuid,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, user_id, role, branch_id)
);

CREATE TABLE core.branches (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    code text NOT NULL,
    name text NOT NULL,
    timezone text NOT NULL DEFAULT 'Asia/Kuala_Lumpur',
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','SUSPENDED','PAYMENT_HOLD','MAINTENANCE','CLOSED')),
    default_pricing_plan_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, code)
);

ALTER TABLE core.tenant_memberships
    ADD CONSTRAINT fk_membership_branch FOREIGN KEY (branch_id) REFERENCES core.branches(id);

CREATE TABLE core.seats (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id uuid NOT NULL REFERENCES core.branches(id),
    code text NOT NULL,
    display_order integer NOT NULL DEFAULT 0,
    status text NOT NULL DEFAULT 'IDLE' CHECK (status IN ('IDLE','ACTIVE','MAINTENANCE','BOOKED','DISABLED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (branch_id, code)
);

CREATE TABLE integration.external_refs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider text NOT NULL,
    resource_type text NOT NULL,
    external_id text NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider, resource_type, external_id)
);

CREATE TABLE core.machines (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id uuid REFERENCES core.branches(id),
    provider text NOT NULL,
    external_ref_id uuid REFERENCES integration.external_refs(id),
    horizon_machine_ref_id uuid REFERENCES integration.external_refs(id),
    resource_profile text NOT NULL,
    gpu_profile text,
    status text NOT NULL DEFAULT 'AVAILABLE' CHECK (status IN ('AVAILABLE','RESERVED','PROVISIONING','READY','IN_USE','OFFLINE','MAINTENANCE','FAILED','RETIRED')),
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE core.seat_machine_assignments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    seat_id uuid NOT NULL REFERENCES core.seats(id),
    machine_id uuid NOT NULL REFERENCES core.machines(id),
    valid_from timestamptz NOT NULL,
    valid_to timestamptz,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','ENDED')),
    CHECK (valid_to IS NULL OR valid_to > valid_from)
);
CREATE UNIQUE INDEX uq_active_seat_assignment ON core.seat_machine_assignments(seat_id) WHERE valid_to IS NULL AND status = 'ACTIVE';

-- Gaming domain
CREATE TABLE gaming.gamers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    external_ref text,
    display_name text NOT NULL,
    phone text,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED','BLOCKED')),
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, external_ref)
);

CREATE TABLE gaming.games (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug text NOT NULL UNIQUE,
    name text NOT NULL,
    publisher text,
    status text NOT NULL DEFAULT 'TESTING' CHECK (status IN ('TESTING','ENABLED','BLOCKED','DEPRECATED')),
    compatibility_profile jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE gaming.game_versions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    game_id uuid NOT NULL REFERENCES gaming.games(id),
    version text NOT NULL,
    image_ref text,
    launcher_ref text,
    status text NOT NULL DEFAULT 'TESTING' CHECK (status IN ('TESTING','PUBLISHED','RETIRED')),
    compatibility jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (game_id, version)
);

CREATE TABLE gaming.sessions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    branch_id uuid NOT NULL REFERENCES core.branches(id),
    seat_id uuid NOT NULL REFERENCES core.seats(id),
    machine_id uuid REFERENCES core.machines(id),
    gamer_id uuid NOT NULL REFERENCES gaming.gamers(id),
    requested_game_id uuid NOT NULL REFERENCES gaming.games(id),
    status text NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','ACCEPTED','PROVISIONING','READY','CONNECTING','CONNECTED','ACTIVE','DISCONNECTED','RECONNECTING','ENDING','ENDED','FAILED','CANCELLED','ABANDONED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    accepted_at timestamptz,
    billable_started_at timestamptz,
    ended_at timestamptz,
    termination_reason text,
    request_idem_key text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    UNIQUE (tenant_id, request_idem_key)
);
CREATE INDEX idx_sessions_tenant_status_created ON gaming.sessions(tenant_id, status, created_at DESC);
CREATE INDEX idx_sessions_branch_status ON gaming.sessions(branch_id, status);

CREATE TABLE gaming.provisioning_jobs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id uuid NOT NULL REFERENCES gaming.sessions(id),
    machine_id uuid NOT NULL REFERENCES core.machines(id),
    provider text NOT NULL,
    external_ref_id uuid REFERENCES integration.external_refs(id),
    status text NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','RUNNING','READY','FAILED','CANCELLED','ROLLED_BACK')),
    requested_at timestamptz NOT NULL DEFAULT now(),
    started_at timestamptz,
    completed_at timestamptz,
    failure_code text,
    failure_detail text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX idx_provisioning_session ON gaming.provisioning_jobs(session_id, requested_at);

CREATE TABLE gaming.horizon_sessions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id uuid NOT NULL REFERENCES gaming.sessions(id),
    horizon_session_ref_id uuid UNIQUE REFERENCES integration.external_refs(id),
    horizon_user_ref_id uuid REFERENCES integration.external_refs(id),
    horizon_machine_ref_id uuid REFERENCES integration.external_refs(id),
    state text NOT NULL DEFAULT 'CONNECTED' CHECK (state IN ('CONNECTED','DISCONNECTED','RECONNECTING','ENDED','UNKNOWN')),
    login_at timestamptz,
    logout_at timestamptz,
    last_connected_at timestamptz,
    last_disconnected_at timestamptz,
    connected_seconds bigint NOT NULL DEFAULT 0,
    idle_seconds bigint NOT NULL DEFAULT 0,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX idx_horizon_session_session ON gaming.horizon_sessions(session_id);

CREATE TABLE gaming.game_runs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id uuid NOT NULL REFERENCES gaming.sessions(id),
    game_id uuid NOT NULL REFERENCES gaming.games(id),
    game_version_id uuid REFERENCES gaming.game_versions(id),
    status text NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','STARTING','STARTED','PLAYABLE','PAUSED','EXITED','CRASHED','FAILED','CANCELLED')),
    requested_at timestamptz NOT NULL DEFAULT now(),
    started_at timestamptz,
    playable_at timestamptz,
    ended_at timestamptz,
    exit_reason text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX idx_game_runs_session ON gaming.game_runs(session_id, requested_at);

-- RN-22 fix: device_identities moved up from the "Assets" section.
CREATE TABLE integration.device_identities (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    branch_id uuid REFERENCES core.branches(id),
    seat_id uuid REFERENCES core.seats(id),
    device_type text NOT NULL CHECK (device_type IN ('THIN_CLIENT','GAME_AGENT','OTHER')),
    device_serial text,
    certificate_fingerprint text NOT NULL UNIQUE,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('PENDING','ACTIVE','REVOKED','DISABLED')),
    last_seen_at timestamptz,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_devices_tenant_branch ON integration.device_identities(tenant_id, branch_id);

CREATE TABLE integration.device_enrollment_codes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    branch_id uuid REFERENCES core.branches(id),
    seat_id uuid REFERENCES core.seats(id),
    device_type text NOT NULL CHECK (device_type IN ('THIN_CLIENT','GAME_AGENT','OTHER')),
    code_hash text NOT NULL UNIQUE,
    expires_at timestamptz NOT NULL,
    redeemed_at timestamptz,
    redeemed_device_id uuid REFERENCES integration.device_identities(id),
    created_by uuid REFERENCES identity.users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at > created_at)
);
CREATE INDEX idx_device_enrollment_open ON integration.device_enrollment_codes(tenant_id, expires_at) WHERE redeemed_at IS NULL;

CREATE TABLE integration.session_tickets (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id uuid NOT NULL REFERENCES gaming.sessions(id),
    device_id uuid NOT NULL REFERENCES integration.device_identities(id),
    seat_id uuid NOT NULL REFERENCES core.seats(id),
    machine_id uuid REFERENCES core.machines(id),
    game_id uuid REFERENCES gaming.games(id),
    token_hash text NOT NULL UNIQUE,
    purpose text NOT NULL CHECK (purpose IN ('START_GAME','STOP_GAME','SESSION_CONNECT','STATUS')),
    issued_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    nonce text NOT NULL UNIQUE,
    used_at timestamptz,
    CHECK (expires_at > issued_at)
);
CREATE INDEX idx_session_tickets_session ON integration.session_tickets(session_id, expires_at);
CREATE INDEX idx_session_tickets_device ON integration.session_tickets(device_id, expires_at);

-- Assets
CREATE TABLE integration.assets (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid REFERENCES core.tenants(id),
    owner_type text NOT NULL,
    owner_id text NOT NULL,
    bucket text NOT NULL,
    object_key text NOT NULL UNIQUE,
    content_type text NOT NULL,
    size_bytes bigint,
    sha256 text,
    status text NOT NULL DEFAULT 'PENDING_UPLOAD' CHECK (status IN ('PENDING_UPLOAD','UPLOADED','PROCESSING','READY','REJECTED','DELETED')),
    visibility text NOT NULL DEFAULT 'PRIVATE' CHECK (visibility IN ('PRIVATE','PUBLIC')),
    created_by uuid REFERENCES identity.users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Usage and pricing
ALTER TABLE identity.users ADD CONSTRAINT fk_user_avatar_asset FOREIGN KEY (avatar_asset_id) REFERENCES integration.assets(id);

CREATE TABLE commercial.usage_meters (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    unit text NOT NULL,
    billable_by_default boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE commercial.usage_records (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    session_id uuid NOT NULL REFERENCES gaming.sessions(id),
    game_run_id uuid REFERENCES gaming.game_runs(id),
    meter_id uuid NOT NULL REFERENCES commercial.usage_meters(id),
    start_at timestamptz NOT NULL,
    end_at timestamptz NOT NULL,
    quantity bigint NOT NULL CHECK (quantity >= 0),
    unit text NOT NULL,
    billable boolean NOT NULL DEFAULT false,
    source_event_id uuid,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    CHECK (end_at >= start_at)
);
CREATE INDEX idx_usage_session_start ON commercial.usage_records(session_id, start_at);
CREATE INDEX idx_usage_tenant_start ON commercial.usage_records(tenant_id, start_at);

CREATE TABLE commercial.pricing_plans (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid REFERENCES core.tenants(id),
    name text NOT NULL,
    currency char(3) NOT NULL DEFAULT 'MYR',
    status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','RETIRED')),
    valid_from timestamptz,
    valid_to timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE core.branches ADD CONSTRAINT fk_branch_pricing FOREIGN KEY (default_pricing_plan_id) REFERENCES commercial.pricing_plans(id);

CREATE TABLE commercial.rate_cards (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    pricing_plan_id uuid NOT NULL REFERENCES commercial.pricing_plans(id),
    version integer NOT NULL,
    name text NOT NULL,
    valid_from timestamptz NOT NULL,
    valid_to timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (pricing_plan_id, version),
    CHECK (valid_to IS NULL OR valid_to > valid_from)
);

CREATE TABLE commercial.rate_rules (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    rate_card_id uuid NOT NULL REFERENCES commercial.rate_cards(id),
    meter_id uuid NOT NULL REFERENCES commercial.usage_meters(id),
    resource_profile text,
    game_tier text,
    unit_basis text NOT NULL CHECK (unit_basis IN ('SECOND','MINUTE','HOUR','EVENT','GB')),
    unit_price_minor numeric(20,8) NOT NULL CHECK (unit_price_minor >= 0),
    rounding_increment_seconds integer NOT NULL DEFAULT 1 CHECK (rounding_increment_seconds > 0),
    minimum_charge_minor bigint NOT NULL DEFAULT 0 CHECK (minimum_charge_minor >= 0),
    conditions jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX idx_rate_rules_card ON commercial.rate_rules(rate_card_id);

CREATE TABLE commercial.products (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid REFERENCES core.tenants(id),
    sku text NOT NULL,
    name text NOT NULL,
    product_type text NOT NULL CHECK (product_type IN ('TOPUP','ENTITLEMENT_PACK','SUBSCRIPTION','ADJUSTMENT')),
    price_minor bigint NOT NULL CHECK (price_minor >= 0),
    currency char(3) NOT NULL DEFAULT 'MYR',
    status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','RETIRED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, sku)
);

CREATE TABLE commercial.product_entitlements (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id uuid NOT NULL REFERENCES commercial.products(id),
    entitlement_code text NOT NULL,
    quantity bigint NOT NULL CHECK (quantity > 0),
    unit text NOT NULL
);

CREATE TABLE commercial.commercial_accounts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL UNIQUE REFERENCES core.tenants(id),
    billing_mode text NOT NULL CHECK (billing_mode IN ('PREPAID','POSTPAID')),
    currency char(3) NOT NULL DEFAULT 'MYR',
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','CLOSED')),
    credit_limit_minor bigint NOT NULL DEFAULT 0 CHECK (credit_limit_minor >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE commercial.wallets (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    commercial_account_id uuid NOT NULL REFERENCES commercial.commercial_accounts(id),
    wallet_type text NOT NULL DEFAULT 'PREPAID_SERVICE' CHECK (wallet_type IN ('PREPAID_SERVICE','PROMO')),
    currency char(3) NOT NULL DEFAULT 'MYR',
    available_minor bigint NOT NULL DEFAULT 0,
    held_minor bigint NOT NULL DEFAULT 0,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','LOCKED','CLOSED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (commercial_account_id, wallet_type)
);

CREATE TABLE commercial.wallet_holds (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    wallet_id uuid NOT NULL REFERENCES commercial.wallets(id),
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    purpose text NOT NULL,
    reference_type text,
    reference_id uuid,
    status text NOT NULL DEFAULT 'HELD' CHECK (status IN ('HELD','RELEASED','CAPTURED','EXPIRED','CANCELLED')),
    idempotency_key text NOT NULL,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (wallet_id, idempotency_key)
);
CREATE INDEX idx_wallet_holds_active ON commercial.wallet_holds(wallet_id, status, expires_at);

CREATE TABLE commercial.entitlement_grants (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    commercial_account_id uuid NOT NULL REFERENCES commercial.commercial_accounts(id),
    product_id uuid REFERENCES commercial.products(id),
    entitlement_code text NOT NULL,
    quantity_granted bigint NOT NULL CHECK (quantity_granted > 0),
    quantity_consumed bigint NOT NULL DEFAULT 0 CHECK (quantity_consumed >= 0),
    source_type text NOT NULL,
    source_id uuid,
    expires_at timestamptz,
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','EXHAUSTED','EXPIRED','REVOKED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (quantity_consumed <= quantity_granted)
);
CREATE INDEX idx_entitlement_account_code ON commercial.entitlement_grants(commercial_account_id, entitlement_code, status);

-- Billing / charges
CREATE TABLE billing.charges (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES core.tenants(id),
    commercial_account_id uuid NOT NULL REFERENCES commercial.commercial_accounts(id),
    session_id uuid REFERENCES gaming.sessions(id),
    usage_record_id uuid REFERENCES commercial.usage_records(id),
    pricing_rule_id uuid REFERENCES commercial.rate_rules(id),
    quantity bigint NOT NULL CHECK (quantity >= 0),
    unit_basis text NOT NULL,
    unit_price_minor numeric(20,8) NOT NULL CHECK (unit_price_minor >= 0),
    subtotal_minor bigint NOT NULL CHECK (subtotal_minor >= 0),
    tax_minor bigint NOT NULL DEFAULT 0 CHECK (tax_minor >= 0),
    total_minor bigint NOT NULL CHECK (total_minor >= 0),
    currency char(3) NOT NULL DEFAULT 'MYR',
    status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','POSTED','VOIDED','REFUNDED','PARTIALLY_REFUNDED')),
    pricing_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_charges_account_created ON billing.charges(commercial_account_id, created_at DESC);
CREATE INDEX idx_charges_session ON billing.charges(session_id);

CREATE TABLE billing.invoices (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    commercial_account_id uuid NOT NULL REFERENCES commercial.commercial_accounts(id),
    branch_id uuid REFERENCES core.branches(id),
    invoice_number text NOT NULL UNIQUE,
    status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ISSUED','PAID','PARTIALLY_PAID','OVERDUE','VOID','CREDITED')),
    subtotal_minor bigint NOT NULL DEFAULT 0,
    tax_minor bigint NOT NULL DEFAULT 0,
    total_minor bigint NOT NULL DEFAULT 0,
    currency char(3) NOT NULL DEFAULT 'MYR',
    issued_at timestamptz,
    due_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE billing.invoice_lines (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    invoice_id uuid NOT NULL REFERENCES billing.invoices(id),
    charge_id uuid REFERENCES billing.charges(id),
    description text NOT NULL,
    quantity bigint NOT NULL DEFAULT 1,
    unit_price_minor numeric(20,8) NOT NULL DEFAULT 0,
    subtotal_minor bigint NOT NULL DEFAULT 0
);

CREATE TABLE billing.receivables (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    commercial_account_id uuid NOT NULL REFERENCES commercial.commercial_accounts(id),
    invoice_id uuid NOT NULL REFERENCES billing.invoices(id),
    amount_minor bigint NOT NULL CHECK (amount_minor >= 0),
    outstanding_minor bigint NOT NULL CHECK (outstanding_minor >= 0),
    due_at timestamptz,
    status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','PARTIALLY_PAID','PAID','WRITTEN_OFF')),
    created_at timestamptz NOT NULL DEFAULT now()
);

-- Payments / settlements
CREATE TABLE payments.payment_orders (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    commercial_account_id uuid NOT NULL REFERENCES commercial.commercial_accounts(id),
    provider text,
    provider_order_ref text,
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    currency char(3) NOT NULL DEFAULT 'MYR',
    purpose text NOT NULL CHECK (purpose IN ('WALLET_TOPUP','PRODUCT_PURCHASE','INVOICE_PAYMENT')),
    status text NOT NULL DEFAULT 'CREATED' CHECK (status IN ('CREATED','PENDING','PROCESSING','SUCCEEDED','FAILED','EXPIRED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED','DISPUTED')),
    checkout_url text,
    qr_payload text,
    expires_at timestamptz,
    idempotency_key text NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (commercial_account_id, idempotency_key)
);

CREATE TABLE payments.payment_transactions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    payment_order_id uuid NOT NULL REFERENCES payments.payment_orders(id),
    provider_transaction_ref text NOT NULL,
    payment_method text,
    status text NOT NULL CHECK (status IN ('PENDING','PROCESSING','SUCCEEDED','FAILED','REVERSED','REFUNDED','DISPUTED')),
    amount_minor bigint NOT NULL,
    currency char(3) NOT NULL,
    provider_payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider_transaction_ref)
);

CREATE TABLE payments.webhook_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider text NOT NULL,
    provider_event_ref text NOT NULL,
    payment_transaction_id uuid REFERENCES payments.payment_transactions(id),
    event_type text NOT NULL,
    signature_valid boolean NOT NULL DEFAULT false,
    payload_sha256 text NOT NULL,
    payload jsonb NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    status text NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','PROCESSED','REJECTED','FAILED_RETRYING','DEAD_LETTER')),
    UNIQUE (provider, provider_event_ref)
);

CREATE TABLE payments.refunds (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    payment_transaction_id uuid NOT NULL REFERENCES payments.payment_transactions(id),
    provider_ref text,
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    currency char(3) NOT NULL,
    reason text NOT NULL,
    status text NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','PROCESSING','SUCCEEDED','FAILED')),
    idempotency_key text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (payment_transaction_id, idempotency_key)
);

CREATE TABLE payments.settlements (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    provider text NOT NULL,
    settlement_ref text NOT NULL,
    currency char(3) NOT NULL,
    gross_minor bigint NOT NULL,
    fees_minor bigint NOT NULL DEFAULT 0,
    net_minor bigint NOT NULL,
    status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SETTLED','MISMATCH','REVIEW')),
    settlement_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider, settlement_ref)
);

CREATE TABLE payments.settlement_lines (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    settlement_id uuid NOT NULL REFERENCES payments.settlements(id),
    payment_transaction_id uuid REFERENCES payments.payment_transactions(id),
    amount_minor bigint NOT NULL,
    status text NOT NULL DEFAULT 'MATCHED' CHECK (status IN ('MATCHED','MISSING','DUPLICATE','MISMATCH')),
    mismatch_reason text
);

-- Double-entry ledger
CREATE TABLE ledger.accounts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    commercial_account_id uuid REFERENCES commercial.commercial_accounts(id),
    code text NOT NULL,
    name text NOT NULL,
    account_type text NOT NULL CHECK (account_type IN ('ASSET','LIABILITY','REVENUE','EXPENSE','RECEIVABLE','EQUITY')),
    currency char(3) NOT NULL DEFAULT 'MYR',
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','CLOSED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (commercial_account_id, code)
);

CREATE TABLE ledger.journal_entries (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    entry_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    tenant_id uuid REFERENCES core.tenants(id),
    source_type text NOT NULL,
    source_id uuid,
    description text NOT NULL,
    status text NOT NULL DEFAULT 'POSTED' CHECK (status IN ('POSTED','VOIDED')),
    idempotency_key text NOT NULL UNIQUE,
    posted_at timestamptz NOT NULL DEFAULT now(),
    created_by_service text NOT NULL
);

CREATE TABLE ledger.journal_lines (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    journal_entry_id uuid NOT NULL REFERENCES ledger.journal_entries(id),
    ledger_account_id uuid NOT NULL REFERENCES ledger.accounts(id),
    debit_minor bigint NOT NULL DEFAULT 0 CHECK (debit_minor >= 0),
    credit_minor bigint NOT NULL DEFAULT 0 CHECK (credit_minor >= 0),
    currency char(3) NOT NULL,
    reference_type text,
    reference_id uuid,
    CHECK ((debit_minor = 0) <> (credit_minor = 0))
);
CREATE INDEX idx_journal_lines_entry ON ledger.journal_lines(journal_entry_id);
CREATE INDEX idx_journal_entries_source ON ledger.journal_entries(source_type, source_id);

-- Durable event delivery
CREATE TABLE integration.domain_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type text NOT NULL,
    event_version integer NOT NULL DEFAULT 1,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    tenant_id uuid REFERENCES core.tenants(id),
    correlation_id uuid NOT NULL,
    causation_id uuid,
    occurred_at timestamptz NOT NULL,
    producer text NOT NULL,
    payload jsonb NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_domain_events_aggregate ON integration.domain_events(aggregate_type, aggregate_id, occurred_at);
CREATE INDEX idx_domain_events_tenant_time ON integration.domain_events(tenant_id, occurred_at DESC);

CREATE TABLE integration.outbox_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    domain_event_id uuid NOT NULL UNIQUE REFERENCES integration.domain_events(id),
    status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','PUBLISHED','FAILED','DEAD_LETTER')),
    attempts integer NOT NULL DEFAULT 0,
    available_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_outbox_pending ON integration.outbox_events(status, available_at);

CREATE TABLE integration.inbox_events (
    consumer_name text NOT NULL,
    event_id uuid NOT NULL,
    processed_at timestamptz NOT NULL DEFAULT now(),
    result_hash text,
    PRIMARY KEY (consumer_name, event_id)
);

CREATE TABLE audit.events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid REFERENCES core.tenants(id),
    actor_type text NOT NULL,
    actor_id text,
    action text NOT NULL,
    resource_type text,
    resource_id text,
    outcome text NOT NULL CHECK (outcome IN ('SUCCESS','DENIED','ERROR')),
    ip_address inet,
    user_agent text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_tenant_time ON audit.events(tenant_id, occurred_at DESC);

INSERT INTO commercial.usage_meters(code, name, unit, billable_by_default)
VALUES
 ('PLAYABLE_GAMING_TIME','Playable gaming time','second',true),
 ('HORIZON_CONNECTED_TIME','Horizon connected time','second',false),
 ('SEAT_TIME','Seat occupied time','second',false),
 ('PROVISIONING_TIME','Provisioning duration','second',false),
 ('GAME_LAUNCH','Game launch','event',false)
ON CONFLICT (code) DO NOTHING;

COMMIT;
